#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Change to the module root (the directory containing this script)\ncd "$(dirname "$0")/.."\n\n# Initialize Terraform without a backend (offline safe)\nterraform init -backend=false > /dev/null\n\n# Validate the configuration\nterraform validate\n\n# Run a plan and capture output (no apply)\nPLAN_OUTPUT=$(terraform plan -input=false -no-color -out=plan.out 2>&1)\n\n# Ensure the plan contains the expected resources\nif echo "$PLAN_OUTPUT" | grep -q "aws_s3_bucket.safehouse" && \
   echo "$PLAN_OUTPUT" | grep -q "aws_s3_bucket_versioning.safehouse_versioning" && \
   echo "$PLAN_OUTPUT" | grep -q "aws_s3_bucket_server_side_encryption_configuration.safehouse_encryption"; then\n  echo "✅ Terraform module test passed"\n  exit 0\nelse\n  echo "❌ Terraform module test failed"\n  exit 1\nfi\n
